//! Committed outputs generated by the pinned Go implementation, not hand-written
//! expectations. The oracle is development-only and is not needed by `cargo test`.
use relaykit::{Context, Format, PreparedRequest, Request};
use serde_json::{Value, json};
use std::sync::Arc;

// The fixtures passed through Python's JSON encoder, which spells 1e-6 as
// 1e-06. With arbitrary_precision, serde_json compares Number lexemes instead
// of their values. Compare decimal coefficients exactly: coercing every number
// to f64 would hide regressions in large integers and raw JSON islands.
fn decimal(number: &serde_json::Number) -> Option<(bool, String, i64)> {
    let text = number.to_string();
    let (coefficient, exponent) = text.split_once(['e', 'E']).unwrap_or((&text, "0"));
    let exponent = exponent.parse::<i64>().ok()?;
    let negative = coefficient.starts_with('-');
    let coefficient = coefficient.strip_prefix('-').unwrap_or(coefficient);
    let (whole, fraction) = coefficient.split_once('.').unwrap_or((coefficient, ""));
    let digits = format!("{whole}{fraction}");
    let digits = digits.trim_start_matches('0');
    if digits.is_empty() {
        return Some((negative, "0".into(), 0));
    }
    let significant = digits.trim_end_matches('0');
    let exponent = exponent
        .checked_sub(fraction.len() as i64)?
        .checked_add((digits.len() - significant.len()) as i64)?;
    Some((negative, significant.into(), exponent))
}

fn equivalent(actual: &Value, expected: &Value) -> bool {
    match (actual, expected) {
        (Value::Number(actual), Value::Number(expected)) => {
            actual == expected
                || decimal(actual).is_some_and(|value| Some(value) == decimal(expected))
        }
        (Value::Array(actual), Value::Array(expected)) => {
            actual.len() == expected.len()
                && actual.iter().zip(expected).all(|(a, b)| equivalent(a, b))
        }
        (Value::Object(actual), Value::Object(expected)) => {
            actual.len() == expected.len()
                && actual.iter().all(|(key, value)| {
                    expected
                        .get(key)
                        .is_some_and(|expected| equivalent(value, expected))
                })
        }
        _ => actual == expected,
    }
}

#[test]
fn json_number_comparison_keeps_exact_values_and_argument_strings() {
    let parse = |text| serde_json::from_str::<Value>(text).unwrap();
    assert!(equivalent(&parse("1e-6"), &parse("1e-06")));
    assert!(equivalent(&parse("1e-6"), &parse("0.000001")));
    assert!(equivalent(&parse("1.0"), &parse("1")));
    assert!(equivalent(&parse("-0.0"), &parse("-0")));
    assert!(!equivalent(&parse("-0"), &parse("0")));
    assert!(!equivalent(
        &parse("9007199254740993"),
        &parse("9007199254740992")
    ));
    assert!(!equivalent(&json!("{\"x\":1e-6}"), &json!("{\"x\":1e-06}")));
}

#[test]
fn upstream_request_edge_cases() {
    let corpus: Value = serde_json::from_str(include_str!("fixtures/request_parity.json")).unwrap();
    let mut failures = Vec::new();
    for entry in corpus.as_array().unwrap() {
        let case = &entry["case"];
        if let Ok(filter) = std::env::var("CASE_FILTER") {
            if !case["name"].as_str().unwrap().contains(&filter) {
                continue;
            }
        }
        let from: Format = case["from"].as_str().unwrap().parse().unwrap();
        let to: Format = case["to"].as_str().unwrap().parse().unwrap();
        let model = case["model"].as_str().unwrap_or("");
        let mut ctx = Context {
            channel_meta_attached: !model.is_empty(),
            upstream_model_name: model.into(),
            ..Default::default()
        };
        ctx.media.get_base64_data =
            Some(Arc::new(|_, _| Ok(("aGVsbG8=".into(), "image/png".into()))));
        ctx.media.decode_base64_file_data =
            Some(Arc::new(|_| Ok(("aGVsbG8=".into(), "image/png".into()))));
        if case["golden"] == true {
            ctx.options.gemini.function_call_thought_signature_enabled = true;
            ctx.options.gemini.thinking_adapter_budget_tokens_percentage = 0.6;
            ctx.options.gemini.safety_setting = Some(Arc::new(|_| "OFF".into()));
        }
        let result = Request::from_value(from, case["input"].clone())
            .and_then(|request| relaykit::convert_request(&ctx, to, &request));
        let expected = &entry["expected"];
        let actual = match result {
            Ok(result) => {
                json!({"value": result.value.into_value(), "diagnostics": result.diagnostics})
            }
            Err(error) => json!({"error": error.to_string()}),
        };
        if actual.get("error").is_some() && expected.get("error").is_some() {
            continue;
        }
        let wanted = if expected.get("error").is_some() {
            json!({"error": expected["error"]})
        } else {
            json!({"value": expected["value"], "diagnostics": expected["diagnostics"].as_array().cloned().unwrap_or_default()})
        };
        if !equivalent(&actual, &wanted) {
            failures.push(json!({"case":case, "actual":actual, "expected":wanted}));
        }
    }
    if !failures.is_empty() {
        let path = std::env::temp_dir().join("relaykit-request-edge-diff.json");
        std::fs::write(&path, serde_json::to_string_pretty(&failures).unwrap()).unwrap();
        panic!(
            "{} request edge cases differ; see {}:\n{}",
            failures.len(),
            path.display(),
            failures
                .iter()
                .map(|v| v["case"]["name"].as_str().unwrap())
                .collect::<Vec<_>>()
                .join("\n")
        );
    }
}

#[test]
fn dynamically_decoded_argument_numbers_match_pinned_go() {
    // Generated by tools/upstream-sync/main.go at the exact module in UPSTREAM.
    // serialized_value retains Go's signed zero, unlike Python's parsed value.
    let corpus: Value =
        serde_json::from_str(include_str!("fixtures/request_json_numbers.json")).unwrap();
    for entry in corpus.as_array().unwrap() {
        let case = &entry["case"];
        let name = case["name"].as_str().unwrap();
        let from: Format = case["from"].as_str().unwrap().parse().unwrap();
        let to: Format = case["to"].as_str().unwrap().parse().unwrap();
        let context = Context {
            channel_meta_attached: true,
            upstream_model_name: case["model"].as_str().unwrap().into(),
            ..Context::default()
        };
        let expected: Value =
            serde_json::from_str(entry["expected"]["serialized_value"].as_str().unwrap()).unwrap();
        let request = Request::from_value(from, case["input"].clone()).unwrap();
        let legacy = relaykit::convert_request(&context, to, &request).unwrap();
        assert!(
            equivalent(legacy.value.as_value(), &expected),
            "{name}: Value differs from Go"
        );

        let bytes = serde_json::to_vec(&case["input"]).unwrap();
        let prepared = PreparedRequest::from_slice(from, &bytes).unwrap();
        let direct = relaykit::convert_prepared_request(&context, to, &prepared).unwrap();
        if from == Format::OpenAiResponses {
            assert!(
                direct.value.is_typed(),
                "{name}: must exercise the typed body"
            );
        }
        assert!(
            equivalent(&direct.value.to_value().unwrap(), &expected),
            "{name}: PreparedRequest differs from Go"
        );
        let mut written = vec![];
        relaykit::convert_request_to_writer(&context, to, &prepared, &mut written).unwrap();
        assert!(
            equivalent(
                &serde_json::from_slice::<Value>(&written).unwrap(),
                &expected
            ),
            "{name}: writer differs from Go"
        );
    }
}
